#!/usr/bin/env bun
/**
 * Docs generator — writes the reference parts of `docs/` from the brick specs.
 *
 *   bun run docs         regenerate docs/primitives/<brick>.md + the index in docs/README.md
 *   bun run docs:check   fail (exit 1) when the committed docs are stale
 *
 * Everything outside the marked blocks is hand-written and preserved:
 * - docs/primitives/<brick>.md: the generated file keeps the content between
 *   `<!-- ui8kit-docs:prose:start -->` / `<!-- ui8kit-docs:prose:end -->` verbatim.
 * - docs/README.md: only `<!-- ui8kit-docs:index:start/end -->` is replaced.
 * - docs/runtimes/*.md, docs/contract.md, docs/primitives/slot.md: fully hand-written.
 *
 * Snippets and rendered DOM come from the same showcase fixtures
 * (`bricks/<brick>/<brick>.data.json`) and the same per-runtime prop translators
 * the parity suites use; the rendered HTML is the canonical renderer's output,
 * which every runtime is parity-tested against (`bun test`).
 */

import { existsSync, readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { bricks } from "../bricks/index";
import { fileStem, type BrickDef, type PartDef, type PropDef } from "../src/domain/model";
import { renderPart } from "../src/domain/render";
import { VOID_TAGS } from "../src/domain/tags";
import { htmlPropName, reactPropName } from "../src/domain/naming";
import { goPackageOf } from "../src/emitters/templ";
import { jinjaTemplateOf } from "../src/emitters/jinja2";
import { phpItemKey, phpParamName } from "../src/emitters/php-common";
import { showcaseCases } from "../tests/support/fixtures";
import {
  hasChildren,
  htmlRuntimeProps,
  knownCanonicalProps,
  reactProps,
  solidProps,
  vueProps,
  type CanonicalProps,
} from "../tests/support/props";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const DOCS = join(ROOT, "docs");
const CHILD = "Content";
const PROSE_START = "<!-- ui8kit-docs:prose:start -->";
const PROSE_END = "<!-- ui8kit-docs:prose:end -->";
const INDEX_START = "<!-- ui8kit-docs:index:start -->";
const INDEX_END = "<!-- ui8kit-docs:index:end -->";
const HEADER = "<!-- Generated by `bun run docs` from bricks/*/*.def.ts + *.data.json. Edit only the prose block below; everything else is overwritten. -->";

// ---------------------------------------------------------------------------
// helpers

const code = (s: string) => "`" + s.replace(/`/g, "\\`") + "`";
const cell = (s: string) => s.replace(/\|/g, "\\|").replace(/\n/g, " ");
const camel = (s: string) => s.charAt(0).toLowerCase() + s.slice(1);
const snake = (s: string) => s.replace(/([a-z0-9])([A-Z])/g, "$1_$2").toLowerCase();
const fence = (lang: string, body: string) => "```" + lang + "\n" + body + "\n```";

const isPlainProp = (p: PropDef) => !["attrs", "children"].includes(p.type) && p.name !== "Class";
const acceptsClass = (part: PartDef) => part.props.some((p) => p.name === "Class");
const acceptsAttrs = (part: PartDef) => part.props.some((p) => p.type === "attrs");
const childrenOk = (part: PartDef, props: CanonicalProps) =>
  hasChildren(part) && !(typeof props["Tag"] === "string" && VOID_TAGS.has(props["Tag"] as string));

function tsType(brick: BrickDef, p: PropDef): string {
  if (p.enumValues?.length) return p.enumValues.map((v) => `"${v}"`).join(" \\| ");
  if (p.type === "items") return `${p.itemsOf ?? "Item"}[]`;
  if (p.type === "bool") return "boolean";
  if (p.type === "int") return "number";
  return "string";
}

interface StateCase {
  id: string;
  props: CanonicalProps;
}

/** Same matrix as the templ/PHP parity suites: defaults, showcase fixtures, every enum value, every boolean. */
function statesFor(brick: BrickDef, part: PartDef): StateCase[] {
  const out: StateCase[] = [{ id: "defaults", props: {} }];
  for (const c of showcaseCases(brick)) {
    const props = knownCanonicalProps(brick, part, c.props);
    if (props && Object.keys(props).length > 0) out.push({ id: c.id, props });
  }
  const settable = (p: PropDef) => !p.passthrough && ["string", "bool"].includes(p.type) && p.name !== "Class";
  for (const p of part.props.filter(settable)) {
    if (p.enumValues?.length) for (const v of p.enumValues) out.push({ id: `${p.name}=${v}`, props: { [p.name]: v } });
    else if (p.type === "bool") out.push({ id: p.name, props: { [p.name]: true } });
  }
  return out;
}

function render(brick: BrickDef, part: PartDef, props: CanonicalProps): string {
  return renderPart(brick, part.name, props, { children: childrenOk(part, props) ? CHILD : undefined });
}

/** Usage case: the first applicable showcase fixture, else defaults. */
function usageCase(brick: BrickDef, part: PartDef): StateCase {
  for (const c of showcaseCases(brick)) {
    const props = knownCanonicalProps(brick, part, c.props);
    if (props && Object.keys(props).length > 0) return { id: c.id, props };
  }
  return { id: "defaults", props: {} };
}

/** Static role/aria attributes and every aria-* attribute the render tree can emit. */
function ariaAttrs(part: PartDef): { statics: string[]; dynamic: string[] } {
  const statics = new Set<string>();
  const dynamic = new Set<string>();
  const walk = (n: unknown): void => {
    if (!n || typeof n !== "object") return;
    if (Array.isArray(n)) return n.forEach(walk);
    const o = n as Record<string, unknown>;
    if (Array.isArray(o["attrs"])) {
      for (const a of o["attrs"] as Array<Record<string, unknown>>) {
        const name = a["name"] as string | undefined;
        if (!name || !(name === "role" || name.startsWith("aria-"))) continue;
        if (a["kind"] === "static") statics.add(`${name}="${a["value"]}"`);
        else dynamic.add(name);
      }
    }
    for (const v of Object.values(o)) if (typeof v === "object") walk(v);
  };
  walk(part.render);
  return { statics: [...statics], dynamic: [...dynamic] };
}

// ---------------------------------------------------------------------------
// per-runtime snippets (translators shared with the parity suites)

const jsLit = (v: unknown): string => {
  if (Array.isArray(v)) return `[${v.map(jsLit).join(", ")}]`;
  if (v && typeof v === "object") {
    const e = Object.entries(v);
    if (!e.length) return "{}";
    return `{ ${e.map(([k, x]) => `${/^[A-Za-z_$][\w$]*$/.test(k) ? k : JSON.stringify(k)}: ${jsLit(x)}`).join(", ")} }`;
  }
  return JSON.stringify(v);
};
const pyLit = (v: unknown): string => {
  if (v === true) return "True";
  if (v === false) return "False";
  if (Array.isArray(v)) return `[${v.map(pyLit).join(", ")}]`;
  if (v && typeof v === "object")
    return `{${Object.entries(v).map(([k, x]) => `'${k}': ${pyLit(x)}`).join(", ")}}`;
  return typeof v === "string" ? `'${v.replace(/'/g, "\\'")}'` : String(v);
};
const phpLit = (v: unknown, latte: boolean): string => {
  if (Array.isArray(v)) return `[${v.map((x) => phpLit(x, latte)).join(", ")}]`;
  if (v && typeof v === "object") {
    const items = Object.entries(v).map(([k, x]) => (latte ? `'${k}' => ${phpLit(x, latte)}` : `${k}: ${phpLit(x, latte)}`));
    return latte ? `[${items.join(", ")}]` : `{ ${items.join(", ")} }`;
  }
  return typeof v === "string" ? `'${v.replace(/'/g, "\\'")}'` : String(v);
};
const goLit = (v: unknown, brick: BrickDef, p?: PropDef): string => {
  if (p?.type === "items") {
    const t = `${goPackageOf(brick)}.${p.itemsOf}`;
    return `[]${t}{${(v as Record<string, unknown>[])
      .map((e) => `{${Object.entries(e).map(([k, x]) => `${k}: ${goLit(x, brick)}`).join(", ")}}`)
      .join(", ")}}`;
  }
  return typeof v === "string" ? JSON.stringify(v) : String(v);
};

function jsxAttrs(props: Record<string, unknown>, braceBool: boolean): string {
  return Object.entries(props)
    .map(([k, v]) =>
      typeof v === "string" ? ` ${k}="${v}"` : v === true && !braceBool ? ` ${k}` : ` ${k}={${jsLit(v)}}`
    )
    .join("");
}

function snippets(brick: BrickDef, part: PartDef, props: CanonicalProps): Array<[string, string, string]> {
  const kids = childrenOk(part, props);
  const name = part.name;
  const pkg = goPackageOf(brick);
  const stem = fileStem(brick);
  const jsx = (attrs: string) => (kids ? `<${name}${attrs}>${CHILD}</${name}>` : `<${name}${attrs} />`);

  const vueAttrs = Object.entries(vueProps(part, props))
    .map(([k, v]) => (typeof v === "string" ? ` ${k}="${v}"` : v === true ? ` ${k}` : ` :${k}='${JSON.stringify(v)}'`))
    .join("");
  const wc = `renderX(${jsLit(htmlRuntimeProps(part, props))}${kids ? `, "${CHILD}"` : ""});`.replace("renderX", `render${name}`);

  const goFields = Object.entries(props)
    .map(([k, v]) => {
      const def = part.props.find((p) => p.name === k);
      const lit = goLit(v, brick, def);
      // templ Value is *string (nullable passthrough): Go 1.26 new(expr)
      return `${k}: ${def?.passthrough && k === "Value" && typeof v === "string" ? `new(${lit})` : lit}`;
    })
    .join(", ");
  const templ = `@${pkg}.${name}(${pkg}.${name}Props{${goFields}})${kids ? ` {\n\t${CHILD}\n}` : ""}`;

  const php = (latte: boolean) =>
    Object.entries(props).map(([k, v]) => {
      const def = part.props.find((p) => p.name === k)!;
      const key = def.type === "attrs" ? "attrs" : phpParamName(def);
      const val =
        def.type === "items"
          ? (v as Record<string, unknown>[]).map((e) => Object.fromEntries(Object.entries(e).map(([a, b]) => [phpItemKey(a), b])))
          : v;
      return `${key}: ${phpLit(val, latte)}`;
    });
  const twigParams = [...php(false), ...(kids ? [`children: '${CHILD}'`] : [])];
  const latteParams = [...php(true), ...(kids ? [`children: '${CHILD}'`] : [])];

  return [
    ["react", "tsx", `import { ${name} } from "./ui/${brick.dir}/${stem}";\n\n${jsx(jsxAttrs(reactProps(part, props), false))}`],
    ["vue", "vue", `<script setup lang="ts">\nimport ${name} from "./ui/${brick.dir}/${name}.vue";\n</script>\n\n<template>\n  ${kids ? `<${name}${vueAttrs}>${CHILD}</${name}>` : `<${name}${vueAttrs} />`}\n</template>`],
    ["svelte", "svelte", `<script lang="ts">\n  import ${name} from "./ui/${brick.dir}/${name}.svelte";\n</script>\n\n${jsx(jsxAttrs(htmlRuntimeProps(part, props), true))}`],
    ["solid", "tsx", `import { ${name} } from "./ui/${brick.dir}/${stem}.solid";\n\n${jsx(jsxAttrs(solidProps(part, props), false))}`],
    ["webcomponent", "ts", `import { render${name} } from "./ui/${brick.dir}/${stem}.wc";\n\ndocument.body.append(${wc.replace(/;$/, "")});`],
    ["templ", "templ", `import "github.com/ui8kit/codegen/generated/templ/ui/${brick.dir}"\n\n${templ}`.replace(`ui/${brick.dir}"`, pkg === brick.dir ? `ui/${brick.dir}"` : `ui/${brick.dir}" // package ${pkg}`)],
    ["twig", "twig", `{% include '${brick.dir}/${name}.html.twig' with { ${twigParams.join(", ")} } only %}`.replace("with {  } only", "only")],
    ["latte", "latte", `{include '${brick.dir}/${name}.latte'${latteParams.length ? ", " + latteParams.join(", ") : ""}}`],
    ["jinja2", "jinja", `{% with p = ${pyLit(props)}${kids ? `, children = '${CHILD}'` : ""} %}{% include '${jinjaTemplateOf(brick, part)}' %}{% endwith %}`],
  ];
}

const RUNTIME_TITLE: Record<string, string> = {
  react: "React", vue: "Vue 3", svelte: "Svelte 5", solid: "SolidJS", webcomponent: "Web Components",
  templ: "Go templ", twig: "Twig", latte: "Latte", jinja2: "Jinja2",
};

// ---------------------------------------------------------------------------
// page

function propsTable(brick: BrickDef, part: PartDef): string {
  const rows = part.props.filter(isPlainProp).map((p) => {
    const req = p.required ? " (required)" : "";
    const def = p.default !== undefined ? code(String(p.default)) : "—";
    const kind = p.passthrough ? "passthrough attr" : p.cva ? "variant" : "prop";
    return `| ${code(p.name)} | ${code(reactPropName(p))} | ${code(htmlPropName(p))} | ${code(tsType(brick, p))}${req} | ${def} | ${kind} | ${cell(p.docs ?? "")} |`;
  });
  if (rows.length === 0) return "_No typed props (only class / attrs / children)._";
  return [
    "| Canonical (templ, Jinja2) | React / Solid | HTML (Svelte, Vue, WC) | Type | Default | Kind | Description |",
    "| --- | --- | --- | --- | --- | --- | --- |",
    ...rows,
  ].join("\n");
}

function variantsSection(brick: BrickDef, part: PartDef): string {
  const cvas = part.props.filter((p) => p.cva);
  const recipe = part.recipeId ? brick.recipes[part.recipeId] : undefined;
  if (!cvas.length || !recipe) return "_No variants: the primitive ships no visual classes; style it with token classes via `class`._";
  const out: string[] = [];
  if (recipe.base.trim()) out.push(`Base classes: ${code(recipe.base.trim())}`, "");
  for (const p of cvas) {
    const key = p.cvaKey ?? p.name.toLowerCase();
    out.push(`**${p.name}** (recipe key ${code(key)}, default ${code(recipe.defaults[key] ?? "—")}):`, "");
    out.push("| Value | Classes |", "| --- | --- |");
    for (const [v, cls] of Object.entries(recipe.byKey[key] ?? {})) out.push(`| ${code(v)} | ${cls ? code(cls) : "—"} |`);
    out.push("");
  }
  return out.join("\n").trimEnd();
}

function partSection(brick: BrickDef, part: PartDef, multi: boolean): string {
  const h = multi ? "###" : "##";
  const { statics, dynamic } = ariaAttrs(part);
  const ariaProps = part.props.filter((p) => p.name.startsWith("Aria"));
  const out: string[] = [];
  if (multi) out.push(`## ${part.name}`, "", part.docs ?? "", "");
  else if (part.docs) out.push(part.docs, "");
  out.push(`${h} Props`, "", propsTable(brick, part), "");
  out.push(
    `Also accepts: ${[
      acceptsClass(part) ? "`class` (`className` in React)" : null,
      acceptsAttrs(part) ? "extra attributes (rest props in JS runtimes, `Attrs` in templ/Jinja2, `attrs` in Twig/Latte; caller wins)" : null,
      hasChildren(part) ? "children" : null,
    ].filter(Boolean).join(", ") || "nothing else"}.`,
    ""
  );
  out.push(`${h} Variants`, "", variantsSection(brick, part), "");
  out.push(`${h} Children`, "");
  out.push(
    hasChildren(part)
      ? "Accepts children (default slot / `children` / `{ children... }` / trusted HTML string in Twig, Latte, Jinja2 — see [runtimes](../runtimes/)). Void tags selected via `tag` render no children."
      : "Void / self-contained element: children are not accepted.",
    ""
  );
  out.push(`${h} ARIA`, "");
  const aria: string[] = [];
  if (statics.length) aria.push(`- Always rendered: ${statics.map(code).join(", ")}.`);
  if (dynamic.length) aria.push(`- Computed/forwarded: ${dynamic.map(code).join(", ")} (omitted when empty).`);
  if (ariaProps.length) aria.push(`- Typed ARIA props: ${ariaProps.map((p) => code(htmlPropName(p))).join(", ")} — static values only.`);
  if (!aria.length) aria.push("- No ARIA attributes are rendered by the primitive; rely on native semantics. Pass extra `aria-*` through attrs.");
  out.push(aria.join("\n"), "");
  if (acceptsClass(part)) {
    out.push(`${h} Classes escape hatch`, "");
    out.push(
      `Compose the part's classes without rendering it (custom root element, no asChild outside React):`,
      "",
      `| Runtime | Helper |`,
      `| --- | --- |`,
      `| React / Solid / Vue / Svelte / WC | ${code(`${camel(part.name)}Classes({ ... })`)} from ${code(`${brick.dir}/${fileStem(brick)}.shared.ts`)} |`,
      `| templ | ${code(`${goPackageOf(brick)}.${part.name}Classes(${goPackageOf(brick)}.${part.name}Props{...})`)} |`,
      `| Twig | ${code(`ui8kit_classes('${camel(part.name)}Classes', { class: '…' })`)} |`,
      `| Latte | ${code(`\\UI8Kit\\Latte\\Classes::${camel(part.name)}Classes(['class' => '…'])`)} |`,
      `| Jinja2 | ${code(`${snake(part.name)}_classes(p)`)} |`,
      ""
    );
    if (part.asChild) out.push("React additionally supports `asChild` (merges props onto the single child via [Slot](slot.md)).", "");
  }
  out.push(`${h} Rendered DOM per state`, "");
  out.push(
    `Canonical renderer output (children = ${code(CHILD)}); all 9 runtimes are parity-tested to produce this DOM.`,
    "",
    "| State | Props | HTML |",
    "| --- | --- | --- |"
  );
  for (const s of statesFor(brick, part)) {
    out.push(`| ${s.id} | ${Object.keys(s.props).length ? code(JSON.stringify(s.props)) : "—"} | ${code(render(brick, part, s.props))} |`);
  }
  out.push("");
  const u = usageCase(brick, part);
  out.push(`${h} Usage`, "");
  out.push(
    `Fixture ${code(u.id)} (${code(JSON.stringify(u.props))}) — every snippet renders:`,
    "",
    fence("html", render(brick, part, u.props)),
    ""
  );
  for (const [rt, lang, body] of snippets(brick, part, u.props)) {
    out.push(`**${RUNTIME_TITLE[rt]}** ([runtime notes](../runtimes/${rt}.md))`, "", fence(lang, body), "");
  }
  return out.join("\n");
}

function prose(path: string, brick: BrickDef): string {
  if (existsSync(path)) {
    const cur = readFileSync(path, "utf8");
    const a = cur.indexOf(PROSE_START);
    const b = cur.indexOf(PROSE_END);
    if (a >= 0 && b > a) return cur.slice(a, b + PROSE_END.length);
  }
  return `${PROSE_START}\n_No additional notes for ${brick.parts[0]!.name} yet._\n${PROSE_END}`;
}

function primitivePage(brick: BrickDef, path: string): string {
  const multi = brick.parts.length > 1;
  const out: string[] = [
    HEADER,
    "",
    `# ${brick.parts[0]!.name}`,
    "",
    `${code(brick.id)} · parts: ${brick.parts.map((p) => code(p.name)).join(", ")} · elements: ${[...new Set(brick.parts.flatMap(partElements))].map((t) => code(`<${t}>`)).join(", ")}`,
    "",
    "## Purpose",
    "",
    brick.docs,
    "",
    "## Notes",
    "",
    prose(path, brick),
    "",
  ];
  if (brick.recordTypes?.length) {
    out.push("## Record types", "");
    for (const r of brick.recordTypes) {
      out.push(`${code(r.name)}: ${r.fields.map((f) => `${code(f.name)} (${f.type})`).join(", ")}`, "");
    }
  }
  for (const part of brick.parts) out.push(partSection(brick, part, multi));
  out.push("---", "", "Rules: [contract](../contract.md) · Index: [docs](../README.md)", "");
  return out.join("\n").replace(/\n{3,}/g, "\n\n");
}

function partElements(part: PartDef): string[] {
  const tags = new Set<string>();
  const walk = (n: unknown): void => {
    if (!n || typeof n !== "object") return;
    if (Array.isArray(n)) return n.forEach(walk);
    const o = n as Record<string, unknown>;
    const t = o["tag"] as Record<string, unknown> | undefined;
    if (o["kind"] === "element" && t) {
      if (t["kind"] === "static") tags.add(t["tag"] as string);
      else if (t["kind"] === "resolved") tags.add(`${t["fallback"]}`);
      else if (Array.isArray(t["tags"])) (t["tags"] as string[]).forEach((x) => tags.add(x));
    }
    for (const v of Object.values(o)) if (typeof v === "object") walk(v);
  };
  walk(part.render);
  return [...tags];
}

function indexBlock(): string {
  const rows = bricks.map((b) => {
    const p = b.parts[0]!;
    return `| [${p.name}](primitives/${b.dir}.md) | ${b.parts.map((x) => code(x.name)).join(", ")} | ${cell(b.docs.split("\n")[0]!.replace(/\.$/, ""))} |`;
  });
  return [
    INDEX_START,
    "| Primitive | Parts | Summary |",
    "| --- | --- | --- |",
    ...rows,
    "| [Slot](primitives/slot.md) | `Slot` | React-only composition helper behind `asChild` (hand-written page) |",
    INDEX_END,
  ].join("\n");
}

// ---------------------------------------------------------------------------

function build(): Map<string, string> {
  const files = new Map<string, string>();
  for (const brick of bricks) {
    const path = join(DOCS, "primitives", `${brick.dir}.md`);
    files.set(path, primitivePage(brick, path));
  }
  const readme = join(DOCS, "README.md");
  const cur = readFileSync(readme, "utf8");
  const a = cur.indexOf(INDEX_START);
  const b = cur.indexOf(INDEX_END);
  if (a < 0 || b < a) throw new Error(`docs/README.md: missing ${INDEX_START} … ${INDEX_END}`);
  files.set(readme, cur.slice(0, a) + indexBlock() + cur.slice(b + INDEX_END.length));
  return files;
}

const check = process.argv.includes("--check");
const files = build();
const stale: string[] = [];
for (const [path, contents] of files) {
  const cur = existsSync(path) ? readFileSync(path, "utf8") : undefined;
  if (cur === contents) continue;
  if (check) stale.push(path.slice(ROOT.length + 1));
  else {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, contents, "utf8");
  }
}
if (check && stale.length) {
  console.error(`docs:check: stale generated docs — run \`bun run docs\`:\n  ${stale.join("\n  ")}`);
  process.exit(1);
}
console.log(check ? `docs:check: OK (${files.size} files up to date).` : `docs: wrote ${files.size} files.`);
